PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "instructors" ("id" integer primary key autoincrement not null, "name" varchar not null, "specialties" text not null, "email" varchar, "phone" varchar, "hourly_rate" numeric not null, "monthly_bonus" numeric, "commission_rate" numeric, "contract_type" varchar check ("contract_type" in ('hourly', 'salary', 'commission')) not null, "status" varchar check ("status" in ('active', 'inactive', 'vacation')) not null default 'active', "join_date" date not null, "total_revenue" numeric not null default '0', "completed_sessions" integer not null default '0', "created_at" datetime, "updated_at" datetime, "slug" varchar, "title" varchar, "image_url" text, "bio" text, "certifications" text, "services" text, "display_order" integer not null default '0', "experience" varchar);
CREATE TABLE IF NOT EXISTS "packages" ("id" integer primary key autoincrement not null, "name" varchar not null, "price" numeric not null, "sessions" integer, "duration" integer not null, "type" varchar not null, "status" varchar check ("status" in ('active', 'inactive')) not null default 'active', "description" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "payroll_agreements" ("id" integer primary key autoincrement not null, "instructor_id" integer not null, "instructor_name" varchar not null, "description" text not null, "type" varchar check ("type" in ('bonus', 'deduction', 'special_rate')) not null, "amount" numeric not null, "is_recurring" tinyint(1) not null default '0', "start_date" date not null, "end_date" date, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("instructor_id") references "instructors"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "work_time_entries" ("id" integer primary key autoincrement not null, "instructor_id" integer not null, "date" date not null, "start_time" time not null, "end_time" time not null, "hours_worked" numeric not null, "description" text not null, "approved" tinyint(1) not null default '0', "approved_by" varchar, "approved_at" datetime, "created_at" datetime, "updated_at" datetime, "status" varchar not null default 'in_progress', "duration" integer, "notes" text, foreign key("instructor_id") references "instructors"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "activity_logs" ("id" integer primary key autoincrement not null, "user_id" integer not null, "action" text not null, "created_at" datetime, "updated_at" datetime, "activity_type" varchar not null, "model_type" varchar, "model_id" integer, "properties" text, "ip_address" varchar, "user_agent" text, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "owner_notifications" ("id" integer primary key autoincrement not null, "type" varchar check ("type" in ('graceful_cancellation', 'package_extension', 'general')) not null, "title" varchar not null, "message" text not null, "trainer_name" varchar not null, "customer_name" varchar not null, "booking_id" varchar, "package_id" varchar, "is_read" tinyint(1) not null default '0', "priority" varchar check ("priority" in ('low', 'medium', 'high')) not null default 'medium', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" varchar not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "class_waitlists" ("id" integer primary key autoincrement not null, "class_id" integer not null, "user_id" integer not null, "position" integer not null, "status" varchar check ("status" in ('waiting', 'notified', 'confirmed', 'expired')) not null default 'waiting', "notified_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("class_id") references "gym_classes"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "class_evaluations" ("id" integer primary key autoincrement not null, "class_id" integer not null, "booking_id" integer, "evaluation_token" varchar not null, "overall_rating" integer not null, "instructor_rating" integer not null, "facility_rating" integer not null, "comments" text, "tags" text, "would_recommend" tinyint(1) not null default '1', "is_submitted" tinyint(1) not null default '0', "sent_at" datetime, "submitted_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("class_id") references "gym_classes"("id") on delete cascade, foreign key("booking_id") references "bookings"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "cancellation_policies" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text not null, "hours_before" integer not null, "penalty_percentage" numeric not null default '0', "allow_reschedule" tinyint(1) not null default '1', "reschedule_hours_before" integer, "max_reschedules_per_month" integer not null default '3', "is_active" tinyint(1) not null default '1', "priority" integer not null default '0', "applicable_to" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "booking_reschedules" ("id" integer primary key autoincrement not null, "booking_id" integer not null, "user_id" integer not null, "original_class_id" integer not null, "new_class_id" integer, "original_datetime" datetime not null, "new_datetime" datetime, "reason" varchar, "status" varchar check ("status" in ('pending', 'approved', 'rejected', 'completed')) not null, "requested_at" datetime not null, "processed_at" datetime, "processed_by" integer, "admin_notes" text, "created_at" datetime, "updated_at" datetime, foreign key("booking_id") references "bookings"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, foreign key("original_class_id") references "gym_classes"("id"), foreign key("new_class_id") references "gym_classes"("id"), foreign key("processed_by") references "users"("id"));
CREATE TABLE IF NOT EXISTS "signatures" ("id" integer primary key autoincrement not null, "user_id" integer not null, "signature_data" text not null, "ip_address" varchar not null, "signed_at" datetime not null, "document_type" varchar not null default 'terms_and_conditions', "document_version" varchar not null default '1.0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "notification_recipients" ("id" integer primary key autoincrement not null, "notification_id" integer not null, "user_id" integer not null, "delivery_channels" text, "delivered_at" datetime, "read_at" datetime, "delivery_status" varchar check ("delivery_status" in ('pending', 'delivered', 'failed')) not null default 'pending', "failure_reason" text, "created_at" datetime, "updated_at" datetime, foreign key("notification_id") references "notifications"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "notification_filters" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "criteria" text not null, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "user_packages" ("id" integer primary key autoincrement not null, "user_id" integer not null, "package_id" integer not null, "name" varchar not null, "assigned_date" date not null, "expiry_date" date not null, "remaining_sessions" integer not null, "total_sessions" integer not null, "created_at" datetime, "updated_at" datetime, "is_frozen" tinyint(1) not null default '0', "frozen_at" datetime, "unfrozen_at" datetime, "freeze_duration_days" integer, "last_notification_sent_at" datetime, "notification_stage" varchar, "auto_renew" tinyint(1) not null default '0', "renewed_from_package_id" integer, "renewed_at" datetime, "status" varchar check ("status" in ('active', 'paused', 'expired', 'expiring_soon', 'frozen')) not null default 'active', foreign key("package_id") references packages("id") on delete cascade on update no action, foreign key("user_id") references users("id") on delete cascade on update no action, foreign key("renewed_from_package_id") references "user_packages"("id"));
CREATE TABLE IF NOT EXISTS "package_history" ("id" integer primary key autoincrement not null, "user_package_id" integer not null, "user_id" integer not null, "action" varchar not null, "previous_status" varchar, "new_status" varchar not null, "sessions_before" integer, "sessions_after" integer, "expiry_date_before" date, "expiry_date_after" date, "notes" text, "performed_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("user_package_id") references "user_packages"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, foreign key("performed_by") references "users"("id"));
CREATE TABLE IF NOT EXISTS "package_notification_logs" ("id" integer primary key autoincrement not null, "user_package_id" integer not null, "user_id" integer not null, "notification_type" varchar not null, "channel" varchar not null, "sent_successfully" tinyint(1) not null default '0', "error_message" text, "days_until_expiry" integer, "created_at" datetime, "updated_at" datetime, foreign key("user_package_id") references "user_packages"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "bulk_operations" ("id" integer primary key autoincrement not null, "type" varchar not null, "performed_by" integer not null, "target_count" integer not null default '0', "successful_count" integer not null default '0', "failed_count" integer not null default '0', "status" varchar check ("status" in ('pending', 'in_progress', 'completed', 'completed_with_errors', 'cancelled', 'failed')) not null default 'pending', "filters" text, "operation_data" text, "errors" text, "started_at" datetime, "completed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("performed_by") references "users"("id"));
CREATE TABLE IF NOT EXISTS "bookings" ("id" integer primary key autoincrement not null, "user_id" integer not null, "customer_name" varchar not null, "customer_email" varchar not null, "class_name" varchar not null, "instructor" varchar not null, "date" date not null, "time" time not null, "status" varchar not null default ('pending'), "type" varchar not null, "attended" tinyint(1), "booking_time" datetime not null, "location" varchar not null, "avatar" varchar, "cancellation_reason" text, "created_at" datetime, "updated_at" datetime, "class_id" integer, "booking_type" varchar not null default 'regular', foreign key("user_id") references users("id") on delete cascade on update no action, foreign key("class_id") references "gym_classes"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "chat_conversations" ("id" integer primary key autoincrement not null, "user_id" integer not null, "status" varchar not null default 'active', "last_message_at" datetime, "unread_count" integer not null default '0', "admin_unread_count" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "chat_messages" ("id" integer primary key autoincrement not null, "conversation_id" integer not null, "sender_id" integer, "content" text not null, "sender_type" varchar not null, "is_read" tinyint(1) not null default '0', "read_at" datetime, "attachment_url" varchar, "attachment_type" varchar, "created_at" datetime, "updated_at" datetime, foreign key("conversation_id") references "chat_conversations"("id") on delete cascade, foreign key("sender_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "store_products" ("id" integer primary key autoincrement not null, "name" varchar not null, "price" numeric not null, "description" text not null, "image_url" varchar, "category" varchar check ("category" in ('supplements', 'apparel', 'accessories', 'equipment')) not null, "slug" varchar not null, "is_active" tinyint(1) not null default '1', "stock_quantity" integer not null default '0', "original_price" numeric, "display_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "orders" ("id" integer primary key autoincrement not null, "order_number" varchar not null, "user_id" integer not null, "status" varchar check ("status" in ('pending', 'processing', 'ready_for_pickup', 'completed', 'cancelled')) not null default 'pending', "subtotal" numeric not null, "tax" numeric not null default '0', "total" numeric not null, "customer_name" varchar not null, "customer_email" varchar not null, "customer_phone" varchar, "notes" text, "ready_at" datetime, "completed_at" datetime, "created_at" datetime, "updated_at" datetime, "points_applied" tinyint(1) not null default '0', "points_awarded" numeric, "points_applied_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "order_items" ("id" integer primary key autoincrement not null, "order_id" integer not null, "product_id" integer not null, "product_name" varchar not null, "price" numeric not null, "quantity" integer not null, "subtotal" numeric not null, "created_at" datetime, "updated_at" datetime, foreign key("order_id") references "orders"("id") on delete cascade, foreign key("product_id") references "store_products"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "specialized_services" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text not null, "icon" varchar, "is_active" tinyint(1) not null default '1', "display_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "appointment_requests" ("id" integer primary key autoincrement not null, "user_id" integer, "specialized_service_id" integer not null, "instructor_id" integer, "client_name" varchar, "client_email" varchar, "client_phone" varchar, "preferred_time_slots" text not null, "notes" text, "status" varchar check ("status" in ('pending', 'confirmed', 'cancelled', 'completed')) not null default 'pending', "confirmed_date" datetime, "confirmed_time" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("specialized_service_id") references "specialized_services"("id") on delete cascade, foreign key("instructor_id") references "instructors"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "referral_codes" ("id" integer primary key autoincrement not null, "user_id" integer not null, "code" varchar not null, "link" varchar not null, "total_referrals" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "referral_rewards" ("id" integer primary key autoincrement not null, "user_id" integer not null, "name" varchar not null, "description" text, "type" varchar check ("type" in ('personal_training', 'discount', 'free_month', 'custom')) not null, "value" numeric, "status" varchar check ("status" in ('available', 'redeemed', 'expired')) not null default 'available', "earned_at" datetime not null, "expires_at" datetime, "redeemed_at" datetime, "referrals_required" integer not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "referrals" ("id" integer primary key autoincrement not null, "referrer_id" integer not null, "referred_user_id" integer not null, "referral_code_id" integer not null, "status" varchar check ("status" in ('pending', 'confirmed', 'rewarded')) not null default 'pending', "joined_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("referrer_id") references "users"("id") on delete cascade, foreign key("referred_user_id") references "users"("id") on delete cascade, foreign key("referral_code_id") references "referral_codes"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "partner_businesses" ("id" integer primary key autoincrement not null, "name" varchar not null, "logo_url" varchar, "description" text, "contact_email" varchar, "contact_phone" varchar, "address" text, "is_active" tinyint(1) not null default '1', "display_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "partner_offers" ("id" integer primary key autoincrement not null, "partner_business_id" integer not null, "title" varchar not null, "description" text not null, "type" varchar check ("type" in ('percentage', 'fixed_amount', 'free_item', 'custom')) not null, "discount_value" numeric, "discount_unit" varchar, "promo_code" varchar, "is_active" tinyint(1) not null default '1', "valid_from" date, "valid_until" date, "usage_limit_per_user" integer not null default '1', "total_usage_limit" integer, "current_usage_count" integer not null default '0', "created_at" datetime, "updated_at" datetime, "discount_percentage" numeric, "usage_limit" integer not null default '0', "used_count" integer not null default '0', foreign key("partner_business_id") references "partner_businesses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "offer_redemptions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "partner_offer_id" integer not null, "verification_code" varchar not null, "status" varchar check ("status" in ('pending', 'used', 'expired')) not null default 'pending', "used_at" datetime, "expires_at" datetime, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("partner_offer_id") references "partner_offers"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "events" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text not null, "date" date not null, "time" time not null, "location" varchar not null, "image_url" varchar, "type" varchar check ("type" in ('social', 'educational', 'fitness', 'other')) not null default 'other', "details" text, "is_active" tinyint(1) not null default '1', "max_attendees" integer, "current_attendees" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "event_r_s_v_p_s" ("id" integer primary key autoincrement not null, "event_id" integer not null, "user_id" integer, "guest_name" varchar, "guest_email" varchar, "response" varchar check ("response" in ('yes', 'no', 'maybe')) not null default 'yes', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("event_id") references "events"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "booking_requests" ("id" integer primary key autoincrement not null, "user_id" integer, "service_type" varchar check ("service_type" in ('ems', 'personal')) not null, "instructor_id" integer, "client_name" varchar not null, "client_email" varchar not null, "client_phone" varchar not null, "preferred_time_slots" text not null, "notes" text, "status" varchar check ("status" in ('pending', 'confirmed', 'rejected', 'cancelled', 'completed')) not null default 'pending', "admin_notes" text, "confirmed_date" date, "confirmed_time" time, "rejection_reason" text, "processed_by" integer, "processed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("instructor_id") references "instructors"("id") on delete set null, foreign key("processed_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "loyalty_points" ("id" integer primary key autoincrement not null, "user_id" integer not null, "amount" numeric not null, "type" varchar not null, "source" varchar not null, "description" varchar not null, "reference_type" varchar, "reference_id" integer, "balance_after" numeric not null, "expires_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "loyalty_rewards" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text not null, "image_url" varchar, "points_cost" integer not null, "validity_days" integer, "type" varchar not null default 'gift', "discount_percentage" numeric, "discount_amount" numeric, "max_redemptions" integer, "current_redemptions" integer not null default '0', "is_active" tinyint(1) not null default '1', "valid_from" datetime, "valid_until" datetime, "terms_conditions" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "loyalty_redemptions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "loyalty_reward_id" integer not null, "points_used" integer not null, "status" varchar not null default 'pending', "redeemed_at" datetime not null, "expires_at" datetime, "used_at" datetime, "redemption_code" varchar not null, "admin_notes" text, "reward_snapshot" text not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("loyalty_reward_id") references "loyalty_rewards"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "referral_reward_tiers" ("id" integer primary key autoincrement not null, "referrals_required" integer not null, "name" varchar not null, "description" text not null, "reward_type" varchar not null, "discount_percentage" numeric, "discount_amount" numeric, "validity_days" integer not null default '90', "quarterly_only" tinyint(1) not null default '1', "next_renewal_only" tinyint(1) not null default '1', "is_active" tinyint(1) not null default '1', "terms_conditions" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "medical_histories" ("id" integer primary key autoincrement not null, "user_id" integer not null, "medical_conditions" text not null, "current_health_problems" text not null, "prescribed_medications" text not null, "smoking" text not null, "physical_activity" text not null, "emergency_contact" text not null, "liability_declaration_accepted" tinyint(1) not null, "submitted_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "parent_consents" ("id" integer primary key autoincrement not null, "user_id" integer not null, "parent_full_name" varchar not null, "father_first_name" varchar not null, "father_last_name" varchar not null, "mother_first_name" varchar not null, "mother_last_name" varchar not null, "parent_birth_date" date not null, "parent_id_number" varchar not null, "parent_phone" varchar not null, "parent_location" varchar not null, "parent_street" varchar not null, "parent_street_number" varchar not null, "parent_postal_code" varchar not null, "parent_email" varchar not null, "consent_accepted" tinyint(1) not null default '1', "signature" text not null, "consent_text" text not null, "consent_version" varchar not null default '1.0', "server_timestamp" datetime not null default CURRENT_TIMESTAMP, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "age_verification_logs" ("id" integer primary key autoincrement not null, "birth_date" date not null, "calculated_age" integer not null, "is_minor" tinyint(1) not null, "server_date" date not null, "ip_address" varchar, "user_agent" text, "created_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "phone" varchar, "membership_type" varchar not null default ('Basic'), "role" varchar not null default ('member'), "join_date" date not null, "remaining_sessions" integer not null default ('0'), "total_sessions" integer not null default ('0'), "last_visit" datetime, "medical_history" text, "avatar" varchar, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "address" varchar, "date_of_birth" date, "emergency_contact" varchar, "emergency_phone" varchar, "notes" text, "notification_preferences" text, "privacy_settings" text, "registration_status" varchar not null default ('pending_terms'), "terms_accepted_at" datetime, "registration_completed_at" datetime, "approved_at" datetime, "approved_by" integer, "status" varchar not null default ('pending_approval'), "ems_interest" tinyint(1) not null default ('0'), "ems_contraindications" text, "ems_liability_accepted" tinyint(1), "is_minor" tinyint(1) not null default ('0'), "age_at_registration" integer, "found_us_via" varchar, "referrer_id" integer, "social_platform" varchar, "referral_code_or_name" varchar, "referral_validated" tinyint(1) not null default '0', "referral_validated_at" datetime, "gender" varchar check ("gender" in ('male', 'female', 'other', 'prefer_not_to_say')), "weight" numeric, "height" numeric, "profile_last_updated" datetime, points INTEGER DEFAULT 0, foreign key("approved_by") references users("id") on delete set null on update no action, foreign key("referrer_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "notifications" ("id" integer primary key autoincrement not null, "title" varchar not null, "message" text not null, "type" varchar check ("type" in ('info', 'warning', 'success', 'error', 'offer', 'party_event', 'order_status', 'chat_message')) not null default 'info', "priority" varchar not null default ('medium'), "channels" text, "filters" text, "created_by" integer, "scheduled_at" datetime, "sent_at" datetime, "status" varchar not null default ('draft'), "total_recipients" integer not null default ('0'), "delivered_count" integer not null default ('0'), "read_count" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, foreign key("created_by") references users("id") on delete set null on update no action);
CREATE TABLE IF NOT EXISTS "progress_photos" ("id" integer primary key autoincrement not null, "user_id" integer not null, "image_path" varchar not null, "caption" text, "uploaded_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "body_measurements" ("id" integer primary key autoincrement not null, "user_id" integer not null, "date" date not null, "weight" numeric, "height" numeric, "waist" numeric, "hips" numeric, "chest" numeric, "arm" numeric, "thigh" numeric, "body_fat" numeric, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "password_resets" ("email" varchar not null, "token" varchar not null, "created_at" datetime);
CREATE TABLE IF NOT EXISTS "gym_classes" ("id" integer primary key autoincrement not null, "name" varchar not null, "type" varchar not null, "instructor" varchar not null, "date" date not null, "time" time not null, "duration" integer not null, "max_participants" integer not null, "current_participants" integer not null default ('0'), "location" varchar not null, "description" text not null, "status" varchar not null default ('active'), "created_at" datetime, "updated_at" datetime, "cancellation_policy_id" integer, foreign key("cancellation_policy_id") references "cancellation_policies"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "cash_register_entries" ("id" integer primary key autoincrement not null, "type" varchar check ("type" in ('income', 'withdrawal')) not null, "amount" numeric not null, "description" text not null, "category" varchar not null, "user_id" integer not null, "payment_method" varchar, "related_entity_id" varchar, "related_entity_type" varchar check ("related_entity_type" in ('customer', 'package', 'expense', 'other')), "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "payment_installments" ("id" integer primary key autoincrement not null, "customer_id" integer not null, "customer_name" varchar not null, "package_id" integer not null, "package_name" varchar not null, "installment_number" integer not null, "total_installments" integer not null, "amount" numeric not null, "due_date" date not null, "paid_date" date, "payment_method" varchar, "status" varchar check ("status" in ('pending', 'paid', 'overdue')) not null default 'pending', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("customer_id") references "users"("id") on delete cascade, foreign key("package_id") references "packages"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "business_expenses" ("id" integer primary key autoincrement not null, "category" varchar check ("category" in ('utilities', 'equipment', 'maintenance', 'supplies', 'marketing', 'other')) not null, "subcategory" varchar not null, "description" text not null, "amount" numeric not null, "date" date not null, "vendor" varchar, "receipt" varchar, "payment_method" varchar not null, "approved" tinyint(1) not null default '0', "approved_by" varchar, "notes" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "points_settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text not null, "type" varchar not null default 'string', "description" text, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "users_points" ("id" integer primary key autoincrement not null, "user_id" integer not null, "points_balance" integer not null default '0', "total_earned" integer not null default '0', "total_spent" integer not null default '0', "lifetime_rank" integer, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "points_transactions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "amount" integer not null, "type" varchar check ("type" in ('earned', 'spent')) not null, "source" varchar not null, "description" text, "balance_after" integer not null, "reference_id" integer, "reference_type" varchar, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "points_rewards" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "points_cost" integer not null, "reward_type" varchar check ("reward_type" in ('gift_card', 'free_session', 'product', 'discount', 'premium', 'merchandise')) not null, "reward_value" varchar not null, "image_url" varchar, "is_active" tinyint(1) not null default '1', "max_redemptions" integer, "current_redemptions" integer not null default '0', "sort_order" integer not null default '0', "terms_conditions" text, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "reward_redemptions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "reward_id" integer not null, "points_spent" integer not null, "reward_code" varchar, "status" varchar check ("status" in ('pending', 'active', 'used', 'expired', 'cancelled')) not null default 'active', "instructions" text, "expires_at" datetime, "used_at" datetime, "used_by_staff_id" integer, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("reward_id") references "points_rewards"("id") on delete cascade, foreign key("used_by_staff_id") references "users"("id") on delete set null);
